void dfs(Map<Integer, List<Integer>> graf, int wezel, Set<Integer> odwiedzone, List<Integer> wynik) {
    odwiedzone.add(wezel); // oznacz PRZED przetworzeniem sasiadow
    wynik.add(wezel);
    for (int sasiad : graf.getOrDefault(wezel, List.of())) {
        if (!odwiedzone.contains(sasiad)) {
            dfs(graf, sasiad, odwiedzone, wynik); // idz GLEBIEJ zanim wrocisz do petli po sasiadach
        }
    }
}
// wywolanie: dfs(graf, 'A', new HashSet<>(), new ArrayList<>())
// dla grafu z VISUAL_EXAMPLE: wynik = [A, B, D, E, C, F]

int liczbaSpojnychSkladowych(Map<Integer, List<Integer>> graf, int liczbaWezlow) {
    Set<Integer> odwiedzone = new HashSet<>();
    int liczbaSkladowych = 0;
    for (int wezel = 0; wezel < liczbaWezlow; wezel++) {
        if (!odwiedzone.contains(wezel)) {
            liczbaSkladowych++; // nowy, nieodwiedzony wezel = nowa spojna skladowa
            dfs(graf, wezel, odwiedzone, new ArrayList<>()); // 'zatop' cala skladowa naraz
        }
    }
    return liczbaSkladowych;
}

